<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import type {AiTaskContext,AiTask,AiTaskPage,AiFailurePage} from '../types/ai-tasks';
import {aiTasksApi} from '../api/ai-tasks';
import {useReadScope} from '../composables/useReadScope';
import PageHeader from '../components/PageHeader.vue';
import ReadOnlyFacts from '../components/ReadOnlyFacts.vue';
import MaterialPreview from '../components/MaterialPreview.vue';
const props=defineProps<{context:AiTaskContext}>(),reads=useReadScope(props.context),api=aiTasksApi(props.context),saved=props.context.memory.aiTasks;
const filters=reactive({q:saved?.q||'',status:saved?.status||''}),cursors=ref(saved?.cursors||['']),index=ref(saved?.index||0),page=ref<AiTaskPage|null>(null),task=ref<AiTask|null>(null),drawer=ref(false),failures=ref<AiFailurePage|null>(null),failureCursors=ref(['0']),failureIndex=ref(0);
const statuses:Record<string,string>={QUEUED:'排队中',WAITING_RESOURCE:'等待资源',RUNNING:'运行中',CANCEL_REQUESTED:'正在取消',AWAITING_CONFIRMATION:'等待确认',PARTIAL_SUCCESS:'部分成功',SUCCEEDED:'已完成',CANCELLED:'已取消',FAILED:'失败',BLOCKED_BY_ENVIRONMENT:'环境不可用',BLOCKED_BY_HARDWARE:'硬件不可用'};
const display=(value:unknown)=>value===null||value===undefined?'未知':String(value);
function remember(){props.context.memory.aiTasks={...filters,cursors:[...cursors.value],index:index.value}}
function close(){reads.cancel('detail');reads.cancel('failures');drawer.value=false;task.value=null;failures.value=null;failureIndex.value=0;failureCursors.value=['0']}
function load(){remember();close();return reads.run('tasks',signal=>api.list(filters.q,filters.status,cursors.value[index.value]||'',signal),value=>{page.value=value})}
function search(){cursors.value=[''];index.value=0;void load()}
function next(){if(!page.value?.next_cursor)return;cursors.value=cursors.value.slice(0,index.value+1);cursors.value.push(page.value.next_cursor);index.value++;void load()}
function detail(row:AiTask){close();drawer.value=true;void reads.run('detail',signal=>api.detail(row.id,signal),value=>{task.value=value})}
function loadFailures(){if(!task.value)return;const id=task.value.id;void reads.run('failures',signal=>api.failures(id,failureCursors.value[failureIndex.value]||'0',signal),value=>{failures.value=value})}
function nextFailure(){if(!failures.value?.next_cursor)return;failureCursors.value=failureCursors.value.slice(0,failureIndex.value+1);failureCursors.value.push(failures.value.next_cursor);failureIndex.value++;loadFailures()}
function legacy(action:'create'|'detail',id?:string){remember();close();props.context.legacyAi(action,id)}
function review(id:string){remember();close();props.context.openAiReview(id)}
onMounted(()=>void load());
</script>
<template><section class="catalog-preview ai-tasks" aria-label="AI标注任务中心"><PageHeader title="AI 标注任务" eyebrow="智能标注 / 项目任务" description="读取原任务与候选事实，创建、重试和完整导出继续使用原工作台。" badge="只读" @back="context.returnToManagement"/><form class="filters" @submit.prevent="search"><el-input v-model="filters.q" maxlength="120" aria-label="搜索AI标注任务" placeholder="任务 ID、名称或模型名称"/><el-select v-model="filters.status" aria-label="AI任务状态"><el-option label="全部状态" value=""/><el-option v-for="(label,value) in statuses" :key="value" :label="label" :value="value"/></el-select><el-button native-type="submit" type="primary" :disabled="reads.busy.tasks">查询任务</el-button><el-button :disabled="reads.busy.tasks" @click="load">刷新</el-button><el-button @click="legacy('create')">原创建入口</el-button></form><el-alert v-if="reads.errors.tasks" :title="reads.errors.tasks" type="error" :closable="false"/><p v-if="reads.errors.tasks&&page">下方为上次读取的结果，请重试刷新。</p><el-alert v-if="page?.indexing" :title="`历史搜索索引准备中：已索引 ${display(page.indexed)}，待处理 ${display(page.remaining)}；请稍后刷新。当前空列表不是零条匹配。`" type="info" :closable="false"/><p v-if="page?.statistics_indexing">部分历史统计正在准备；缺失事实显示未知。</p><el-skeleton v-if="!page&&reads.busy.tasks" :rows="8" animated/><el-table v-if="page&&!page.indexing" :data="page.items" row-key="id" empty-text="当前条件下没有任务"><el-table-column label="任务 / 模型" min-width="220"><template #default="{row}"><strong>{{ row.name||row.id }}</strong><small>{{ row.id }}</small><small>{{ row.model_config_name||'模型名称未提供' }} · {{ row.model_provider||'提供方未提供' }}</small></template></el-table-column><el-table-column label="状态" min-width="140"><template #default="{row}"><el-tag>{{ statuses[row.status]||row.status }}</el-tag><small>{{ row.phase||'阶段未提供' }}</small></template></el-table-column><el-table-column label="生成 / 失败" min-width="170"><template #default="{row}"><span>已处理 {{ display(row.completed_count) }} / {{ display(row.total_count) }}</span><small>失败 {{ display(row.counts.failed) }} · 待处理 {{ display(row.remaining_count) }}</small><small>正式 GT 提交 {{ display(row.counts.gt_committed) }}</small></template></el-table-column><el-table-column prop="created_at" label="创建时间" min-width="170"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="detail(row)">详情</el-button><el-button v-if="row.status==='AWAITING_CONFIRMATION'" link @click="review(row.id)">审核候选</el-button><el-button link @click="legacy('detail',row.id)">原管理</el-button></template></el-table-column></el-table><footer v-if="page&&!page.indexing" class="preview-pagination"><span>第 {{ index+1 }} 页 · 本页 {{ page.items.length }} 条 · 总数未提供</span><div class="preview-actions"><el-button :disabled="!index||reads.busy.tasks" @click="index--;load()">上一页</el-button><el-button :disabled="!page.next_cursor||reads.busy.tasks" @click="next">下一页</el-button></div></footer>
<el-drawer :model-value="drawer" title="AI 标注任务详情" size="min(920px,100vw)" :append-to-body="false" :lock-scroll="false" :before-close="close"><el-skeleton v-if="reads.busy.detail" :rows="8" animated/><el-alert v-else-if="reads.errors.detail" :title="reads.errors.detail" type="error" :closable="false"/><template v-else-if="task"><h2>{{ task.name||task.id }}</h2><ReadOnlyFacts :fields="[['任务 ID',task.id],['状态',statuses[task.status]||task.status],['持久状态',task.persisted_status],['阶段',task.phase],['模型',task.model_config_name],['模型提供方',task.model_provider],['总图片数',display(task.total_count)],['已处理',display(task.completed_count)],['待处理',display(task.remaining_count)],['失败',display(task.counts.failed)],['候选成功',display(task.counts.success)],['合法零框',display(task.counts.empty)],['人工接受',display(task.counts.accepted)],['正式 GT 提交',display(task.counts.gt_committed)],['Worker',task.worker_id],['等待原因',task.resource_wait_reason],['错误',task.error]]"/><p>成功候选与合法零框仍须人工审核；不能直接认定已写入正式 GT。</p><h3>逐图失败记录</h3><el-button :disabled="reads.busy.failures" @click="loadFailures">读取失败图片</el-button><el-alert v-if="reads.errors.failures" :title="reads.errors.failures" type="error" :closable="false"/><el-skeleton v-if="reads.busy.failures" :rows="4" animated/><template v-if="failures"><el-alert v-if="failures.task_error" :title="failures.task_error.message||'任务未生成逐图记录，不能据此认定无失败'" type="warning" :closable="false"/><p>当前失败候选 {{ failures.total }} 张 · 修订 {{ display(failures.review_revision) }}</p><div class="failure-grid"><article v-for="row in failures.items" :key="row.image_id"><MaterialPreview :image="{...row,id:row.image_id}" :project-id="context.projectId" :show-boxes="false"/><h4>{{ row.filename }}</h4><p>{{ row.error_code||'错误码未提供' }} · HTTP {{ display(row.http_status) }}</p><p>{{ row.error||'原因未提供' }}</p><p>{{ row.retry_suggestion||'请到原详情检查配置并重试' }}</p></article></div><div class="preview-actions"><el-button :disabled="!failureIndex||reads.busy.failures" @click="failureIndex--;loadFailures()">上一页失败图</el-button><span>第 {{ failureIndex+1 }} 页</span><el-button :disabled="!failures.next_cursor||reads.busy.failures" @click="nextFailure">下一页失败图</el-button></div></template></template><template #footer><el-button @click="close">返回任务列表</el-button><el-button v-if="task?.status==='AWAITING_CONFIRMATION'" @click="review(task.id)">审核原候选</el-button><el-button v-if="task" type="primary" @click="legacy('detail',task.id)">原重试与完整导出入口</el-button></template></el-drawer></section></template>
<style scoped>
.filters{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.filters>.el-input{flex:1;min-width:180px}.filters>.el-select{width:190px}small{display:block;color:#64748b;margin-top:6px}.failure-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:16px 0}.failure-grid article{border:1px solid #dce4ef;border-radius:12px;padding:12px;overflow-wrap:anywhere;min-width:0}.failure-grid p{font-size:13px;color:#475569}@media(max-width:760px){.failure-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:420px){.failure-grid{grid-template-columns:1fr}}
</style>
